test('Audit failure rolls back profile and consent atomically',function()use($accounts,$db,$first){$id=$first['customer_id'];$before=$accounts->profile(new SyntheticCustomer($id),$id);$n=$db->query('SELECT COUNT(*) FROM customer_consents')->fetchColumn();$db->exec("CREATE TRIGGER customer_test_failure BEFORE INSERT ON customer_security_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic audit failure'");try{no(fn()=>$accounts->updateProfile(new SyntheticCustomer($id),$id,5,'Synthetic Failed'));no(fn()=>$accounts->consent(new SyntheticCustomer($id),$id,5,'privacy','test-v1',true));ok($accounts->profile(new SyntheticCustomer($id),$id)===$before&&$db->query('SELECT COUNT(*) FROM customer_consents')->fetchColumn()===$n);}finally{$db->exec('DROP TRIGGER customer_test_failure');}});
test('Concurrent profile updates serialize with exactly one version winner',function()use($accounts,$first,$argv){$id=$first['customer_id'];$workers=[];for($i=0;$i<2;$i++){$pipes=[];$p=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],$argv[3],'customerworker',$id,'5'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);ok(is_resource($p));fclose($pipes[0]);$workers[]=[$p,$pipes];}$codes=[];foreach($workers as[$p,$pipes]){$codes[]=stream_get_contents($pipes[1]);$e=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);ok(proc_close($p)===0&&$e==='');}sort($codes);ok($codes===['CONFLICT','PASS']);});
